import React, { Component } from 'react';
import {
	CButton,
	CCard,
	CCardBody,
	CCardGroup,
	CCol,
	CContainer,
	CForm,
	CInput,
	CInputGroup,
	CInputGroupPrepend,
	CInputGroupText,
	CRow,
	CSelect,
	CTextarea
} from '@coreui/react';
import CIcon from '@coreui/icons-react';
import StatusModal from '../Modals/StatusModal';
import FailureModal from '../Modals/FailureModal';
import { Loading } from '../Statuses/Statuses';
import { Logger, reloadPage } from '../../Utils/Utils';
import { requestHeaderGETWithAuth, requestHeaderPOSTWithAuth } from '../../Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { BACKEND_TYPING_SPEED_SERVICE_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';

const initialState = {
	isLoaded: false,
	loadingModalVisible: false,
	loadingModalState: 0,
	failureModalVisible: false,
	sourceWebsites: [],
	bulkSaveProgress: null,
	bulkSaveErrors: []
};

const FILE_NAME = "TypingSessionSave.js";

class TypingSessionSave extends Component {

	constructor(props) {
		super(props);
		this.state = JSON.parse(JSON.stringify(initialState));
	}

	resetStateToDefault() {
		this.setState(JSON.parse(JSON.stringify(initialState)));
	}

	componentDidMount() {
		document.title = "Satanlabs - Save Typing Session";
		this.fetchSourceWebsites();
	}

	fetchSourceWebsites() {
		let API_URL = BACKEND_TYPING_SPEED_SERVICE_BASE_URL + '/source/list?offset=0';
		const userData = getUserDataFromLocalStorage();

		fetch(API_URL, requestHeaderGETWithAuth(userData.authToken))
		.then(response => {
			if(response.status === 200)
				return response.json();
			if(response.status === 401) {
				this.setState({
					failureModalVisible: true
				});
				setTimeout(() => {
					logoutProcedureForLocalStorage();
					reloadPage();
				}, 500);
			} else {
				this.setState({
					failureModalVisible: true
				});
			}
			throw new Error("HTTP status is " + response.status);
		})
		.then(
			(result) => {
				Logger(FILE_NAME, "callApi", "FETCH_SOURCES", "result", result);
				if(result.code === 1001) {
					this.setState({
						isLoaded: true,
						sourceWebsites: result.data
					});
				} else {
					this.setState({
						isLoaded: true,
						sourceWebsites: []
					});
				}
			},
			(error) => {
				Logger(FILE_NAME, "callApi", "FETCH_SOURCES", "error", error);
				this.setState({
					isLoaded: true,
					sourceWebsites: []
				});
			}
		);
	}

	reloadData() {
		this.resetStateToDefault();
		this.fetchSourceWebsites();
	}

	submitForm = (event) => {
		event.preventDefault();

		let entry = {
			wpm: parseInt(event.target.inputWpm.value),
			cpm: parseInt(event.target.inputCpm.value),
			accuracy: parseFloat(event.target.inputAccuracy.value),
			typingSourceWebsiteId: parseInt(event.target.inputSourceWebsite.value),
			extraNotes: event.target.inputExtraNotes.value
		};

		if(entry.extraNotes === null || entry.extraNotes.length < 1) {
			entry.extraNotes = null;
		}

		let reqData = [entry];

		this.setState({
			loadingModalVisible: true,
			loadingModalState: 0
		});

		let API_URL = BACKEND_TYPING_SPEED_SERVICE_BASE_URL + '/save';
		const userData = getUserDataFromLocalStorage();
		fetch(API_URL, requestHeaderPOSTWithAuth(JSON.stringify(reqData), userData.authToken))
		.then(response => {
			if(response.status === 200)
				return response.json();
			if(response.status === 401) {
				this.setState({
					loadingModalVisible: false,
					loadingModalState: 0,
					failureModalVisible: true
				});
				setTimeout(() => {
					logoutProcedureForLocalStorage();
					reloadPage();
				}, 500);
			} else {
				this.setState({
					loadingModalVisible: false,
					loadingModalState: 0,
					failureModalVisible: true
				});
			}
			throw new Error("HTTP status is " + response.status);
		})
		.then(
			(result) => {
				Logger(FILE_NAME, "callApi", "FETCH_SAVE", "result", result);
				if(result.code === 1001) {
					//success
					this.setState({
						loadingModalState: 1,
					});
					setTimeout(() => {this.reloadData();}, 200);
				} else {
					//something horrible happened
					this.setState({
						loadingModalVisible: false,
						loadingModalState: 0,
						failureModalVisible: true
					});
				}
			},
			(error) => {
				Logger(FILE_NAME, "callApi", "FETCH_SAVE", "error", error);
				this.setState({
					loadingModalVisible: false,
					loadingModalState: 0,
					failureModalVisible: true
				});
			}
		);
	}

	submitBulkForm = (event) => {
		event.preventDefault();

		const sourceWebsiteId = parseInt(event.target.bulkInputSourceWebsite.value);
		const rawText = event.target.bulkInputText.value;
		const bulkNotes = event.target.bulkInputExtraNotes.value || null;

		if (!sourceWebsiteId) {
			return;
		}

		const lines = rawText.split('\n').filter(line => line.trim().length > 0);
		const regex = /(\d+)\s*WPM\s*\((\d+)\s*CPM\).*?(\d+(?:\.\d+)?)\s*%/i;
		const parsedEntries = [];
		const parseErrors = [];

		lines.forEach((line, index) => {
			const match = line.match(regex);
			if (match) {
				parsedEntries.push({
					wpm: parseInt(match[1]),
					cpm: parseInt(match[2]),
					accuracy: parseFloat(match[3]),
					typingSourceWebsiteId: sourceWebsiteId,
					extraNotes: bulkNotes
				});
			} else {
				parseErrors.push(`Line ${index + 1}: "${line}"`);
			}
		});

		if (parsedEntries.length === 0) {
			this.setState({
				bulkSaveErrors: parseErrors.length > 0 ? parseErrors : ['No valid lines found.']
			});
			return;
		}

		if (parseErrors.length > 0) {
			this.setState({ bulkSaveErrors: parseErrors });
		}

		this.setState({
			bulkSaveProgress: `Saving ${parsedEntries.length} sessions...`,
			loadingModalVisible: true,
			loadingModalState: 0
		});

		const userData = getUserDataFromLocalStorage();
		const API_URL = BACKEND_TYPING_SPEED_SERVICE_BASE_URL + '/save';

		fetch(API_URL, requestHeaderPOSTWithAuth(JSON.stringify(parsedEntries), userData.authToken))
		.then(response => {
			if(response.status === 200)
				return response.json();
			if(response.status === 401) {
				this.setState({
					bulkSaveProgress: null,
					loadingModalVisible: false,
					loadingModalState: 0,
					failureModalVisible: true
				});
				setTimeout(() => {
					logoutProcedureForLocalStorage();
					reloadPage();
				}, 500);
			} else {
				this.setState({
					bulkSaveProgress: null,
					loadingModalVisible: false,
					loadingModalState: 0,
					failureModalVisible: true
				});
			}
			throw new Error("HTTP status is " + response.status);
		})
		.then(
			(result) => {
				Logger(FILE_NAME, "submitBulkForm", "FETCH_BULK_SAVE", "result", result);
				if(result.code === 1001) {
					this.setState({
						bulkSaveProgress: null,
						loadingModalState: 1,
					});
					setTimeout(() => {this.reloadData();}, 200);
				} else {
					this.setState({
						bulkSaveProgress: null,
						loadingModalVisible: false,
						loadingModalState: 0,
						bulkSaveErrors: [...parseErrors, `Server error: ${result.message}`]
					});
				}
			},
			(error) => {
				Logger(FILE_NAME, "submitBulkForm", "FETCH_BULK_SAVE", "error", error);
				this.setState({
					bulkSaveProgress: null,
					loadingModalVisible: false,
					loadingModalState: 0,
					failureModalVisible: true
				});
			}
		);
	}

	render() {
		Logger(FILE_NAME, "render", "", "this.state", this.state);

		return (
			this.state.isLoaded ?
			<div>
				<a href="#/typing-speed" style={{ textDecoration: 'none' }}>
					<CButton color="secondary" className="mb-3">← Back to Typing Sessions</CButton>
				</a>
				<CContainer>
					<CRow className="justify-content-center">
					<CCol md="8">
						<CCardGroup>
						<CCard className="p-4">
							<CCardBody>
							<CForm onSubmit={this.submitForm}>
								<h1>Save Typing Session</h1>
								<CInputGroup className="mb-3">
								<CInputGroupPrepend>
									<CInputGroupText>
									<CIcon name="cilGlobeAlt" />
									</CInputGroupText>
								</CInputGroupPrepend>
								<CSelect
									id="inputSourceWebsite"
									required
								>
									<option value="">-- Select Source Website --</option>
									{
										this.state.sourceWebsites.map(
											sw => <option key={"sw_option_" + sw.id} value={sw.id}>{sw.name}</option>
										)
									}
								</CSelect>
								</CInputGroup>
								<CInputGroup className="mb-3">
								<CInputGroupPrepend>
									<CInputGroupText>
									<CIcon name="cilSpeedometer" />
									</CInputGroupText>
								</CInputGroupPrepend>
								<CInput
									placeholder="WPM (Words Per Minute)"
									autoComplete="on"
									type="number"
									step="1"
									min="1"
									id="inputWpm"
									label="WPM"
									required
								/>
								</CInputGroup>
								<CInputGroup className="mb-3">
								<CInputGroupPrepend>
									<CInputGroupText>
									<CIcon name="cilSpeedometer" />
									</CInputGroupText>
								</CInputGroupPrepend>
								<CInput
									placeholder="CPM (Characters Per Minute)"
									autoComplete="on"
									type="number"
									step="1"
									min="1"
									id="inputCpm"
									label="CPM"
									required
								/>
								</CInputGroup>
								<CInputGroup className="mb-3">
								<CInputGroupPrepend>
									<CInputGroupText>
									<CIcon name="cilChart" />
									</CInputGroupText>
								</CInputGroupPrepend>
								<CInput
									placeholder="Accuracy (0-100)"
									autoComplete="on"
									type="number"
									step="any"
									min="0"
									max="100"
									id="inputAccuracy"
									label="Accuracy"
									required
								/>
								</CInputGroup>
								<CInputGroup className="mb-4">
								<CInputGroupPrepend>
									<CInputGroupText>
									<CIcon name="cilNotes" />
									</CInputGroupText>
								</CInputGroupPrepend>
								<CTextarea
									placeholder='Some extra notes, not-mandatory though'
									id="inputExtraNotes"
									rows="3"
								/>
								</CInputGroup>
								<CRow>
									<CCol xs="6">
										<CButton color="success" className="px-4" type='submit'>SAVE</CButton>
									</CCol>
									<CCol xs="6" className="text-right">
										<CButton color="danger" className="px-0" onClick={() => this.reloadData()}>&nbsp;Reset values&nbsp;</CButton>
									</CCol>
								</CRow>
							</CForm>
							</CCardBody>
						</CCard>
						</CCardGroup>
					</CCol>
					</CRow>
				</CContainer>

				<hr className="my-4" />

				<CContainer>
					<CRow className="justify-content-center">
					<CCol md="8">
						<CCardGroup>
						<CCard className="p-4">
							<CCardBody>
							<CForm onSubmit={this.submitBulkForm}>
								<h1>Bulk Save Sessions</h1>
								<p className="text-muted">
									Paste multiple lines in the format: <code>7 WPM (27 CPM). Your accuracy was 87%</code>
								</p>
								<CInputGroup className="mb-3">
								<CInputGroupPrepend>
									<CInputGroupText>
									<CIcon name="cilGlobeAlt" />
									</CInputGroupText>
								</CInputGroupPrepend>
								<CSelect
									id="bulkInputSourceWebsite"
									required
								>
									<option value="">-- Select Source Website --</option>
									{
										this.state.sourceWebsites.map(
											sw => <option key={"bulk_sw_option_" + sw.id} value={sw.id}>{sw.name}</option>
										)
									}
								</CSelect>
								</CInputGroup>
								<CInputGroup className="mb-3">
								<CInputGroupPrepend>
									<CInputGroupText>
									<CIcon name="cilNotes" />
									</CInputGroupText>
								</CInputGroupPrepend>
								<CTextarea
									placeholder={'Paste lines here, one per line.\nExample:\n7 WPM (27 CPM). Your accuracy was 87%\n45 WPM (225 CPM). Your accuracy was 95.5%'}
									id="bulkInputText"
									rows="10"
									required
								/>
								</CInputGroup>
								<CInputGroup className="mb-3">
								<CInputGroupPrepend>
									<CInputGroupText>
									<CIcon name="cilNotes" />
									</CInputGroupText>
								</CInputGroupPrepend>
								<CInput
									placeholder='Notes (optional, applied to all entries)'
									id="bulkInputExtraNotes"
									type="text"
								/>
								</CInputGroup>
								{this.state.bulkSaveProgress &&
									<p className="text-info font-weight-bold mb-3">{this.state.bulkSaveProgress}</p>
								}
								{this.state.bulkSaveErrors.length > 0 &&
									<div className="mb-3">
										<p className="text-warning font-weight-bold">The following lines could not be parsed or failed:</p>
										<ul>
											{this.state.bulkSaveErrors.map((err, idx) =>
												<li key={"bulk_err_" + idx} className="text-danger">{err}</li>
											)}
										</ul>
									</div>
								}
								<CRow>
									<CCol xs="6">
										<CButton color="primary" className="px-4" type='submit' disabled={!!this.state.bulkSaveProgress}>SAVE ALL</CButton>
									</CCol>
								</CRow>
							</CForm>
							</CCardBody>
						</CCard>
						</CCardGroup>
					</CCol>
					</CRow>
				</CContainer>

				<StatusModal visible={this.state.loadingModalVisible} loadingModalState={this.state.loadingModalState} />
				<FailureModal visible={this.state.failureModalVisible} />
			</div> : <Loading />
		);
	}
}

export default TypingSessionSave;
